# One test per fixture in tests/testthat/fixtures/gaugings/. The files are
# regenerated by make-fixtures.R there; each stands for a way real
# gauging exports differ from one another.

fx <- function(name) testthat::test_path("fixtures", "gaugings", name)
rd <- function(name, ...) read_gaugings(fx(name), quiet = TRUE, ...)
at_utc <- function(x) as.POSIXct(x, tz = "UTC")

test_that("01 a clean export reads with no notes", {
  out <- rd("01_clean_wiski.csv")
  expect_equal(nrow(out), 3L)
  expect_true(all(is.na(out$read_issue)))
  expect_equal(out$stage_m, c(1.6, 0.85, 1.885))
  expect_equal(out$observation_time[1], at_utc("1970-02-13 12:47:00"))
  expect_equal(nrow(read_summary(out)), 0L)
})

test_that("02 semicolons are detected and a decimal comma needs dec = ','", {
  out <- rd("02_semicolon_decimal_comma.csv", dec = ",")
  expect_equal(out$stage_m, c(1.6, 0.85))
  expect_equal(out$discharge_cms, c(53.3371, 6.6824))
  expect_true(all(is.na(out$read_issue)))
  # Without dec = "," the comma is not guessed at: it is noted.
  raw <- rd("02_semicolon_decimal_comma.csv")
  expect_true(all(is.na(raw$stage_m)))
  expect_match(raw$read_issue[1], "stage not a number")
  expect_equal(raw$stage_original, c("1,6", "0,85"))
})

test_that("03 tab-delimited and 04 pipe-delimited files read the same", {
  tab <- rd("03_tab_delimited.tsv")
  pipe <- rd("04_pipe_delimited.txt")
  expect_equal(tab$stage_m, c(1.6, 0.85))
  expect_equal(pipe$discharge_cms, c(53.3371, 6.6824))
  expect_equal(tab$station_id, pipe$station_id)
  expect_equal(rd("03_tab_delimited.tsv", sep = "\t")$stage_m, tab$stage_m)
})

test_that("05 placeholders become missing, and each is noted, with the original kept", {
  out <- rd("05_placeholders.csv")
  expect_equal(nrow(out), 4L)
  expect_true(is.na(out$stage_m[1]) && is.na(out$discharge_cms[2]) && is.na(out$stage_m[3]) && is.na(out$discharge_cms[3]))
  expect_equal(out$read_issue[1], "stage missing")
  expect_equal(out$read_issue[2], "discharge missing")
  expect_equal(out$read_issue[3], "stage missing; discharge missing")
  expect_true(is.na(out$read_issue[4]))
  expect_equal(out$stage_original[1], "---")
  expect_equal(out$discharge_original[2], "NULL")
})

test_that("06 text that is not a number is noted and kept, never turned into a value", {
  out <- rd("06_unparseable_numbers.csv")
  expect_equal(out$read_issue[1], "stage not a number")
  expect_equal(out$read_issue[2], "discharge not a number")
  expect_equal(out$read_issue[3], "stage not a number")
  expect_true(is.na(out$read_issue[4]))
  expect_equal(out$stage_original, c("1.6m", "0.85", "1,6", "0.9"))
  expect_true(is.na(out$stage_m[1]))
})

test_that("07 a blank station id is noted and the row stays", {
  out <- rd("07_blank_station.csv")
  expect_equal(nrow(out), 2L)
  expect_equal(out$read_issue[1], "station id missing")
  expect_true(is.na(out$station_id[1]))
})

test_that("08 a month-first file is detected from a date that can only be month-first", {
  out <- rd("08_month_first_dates.csv")
  expect_equal(out$observation_time[1], at_utc("1970-03-25 12:47:00"))
  expect_equal(out$observation_time[2], at_utc("1970-05-05 13:02:00"))
  expect_true(all(is.na(out$read_issue)))
  expect_equal(attr(read_summary(out), "date_format"), "%m/%d/%Y")
})

test_that("09 genuinely ambiguous dates warn, and date_format settles it", {
  expect_warning(out <- rd("09_ambiguous_dates.csv"), "day-first and month-first")
  expect_equal(as.Date(out$observation_time[1]), as.Date("2020-04-03"))
  expect_no_warning(mf <- rd("09_ambiguous_dates.csv", date_format = "%m/%d/%Y"))
  expect_equal(as.Date(mf$observation_time[1]), as.Date("2020-03-04"))
})

test_that("10 ISO dates read", {
  out <- rd("10_iso_dates.csv")
  expect_equal(out$observation_time[2], at_utc("1970-05-05 13:02:00"))
  expect_equal(attr(read_summary(out), "date_format"), "%Y-%m-%d")
})

test_that("11 a single date-time column reads when named with datetime =", {
  out <- rd("11_datetime_single_column.csv", datetime = "When")
  expect_equal(out$observation_time, at_utc(c("2020-03-04 12:30:00", "2020-03-05 08:15:30")))
  expect_true(all(is.na(out$read_issue)))
  expect_true("datetime_original" %in% names(out))
  expect_false("date_original" %in% names(out))
})

test_that("12 a missing time is midnight, and says so", {
  out <- rd("12_missing_time.csv")
  expect_equal(out$observation_time[1], at_utc("1970-02-13 00:00:00"))
  expect_equal(out$read_issue[1], "time missing, midnight assumed")
  expect_true(is.na(out$read_issue[2]))
  expect_true(is.na(rd("12_missing_time.csv", time = NULL)$read_issue[1]))
})

test_that("13 a time that is not a time is noted", {
  out <- rd("13_bad_time.csv")
  expect_match(out$read_issue[1], "time not read")
})

test_that("14 dates outside 1800 to next year are noted", {
  out <- rd("14_date_out_of_range.csv")
  expect_match(out$read_issue[1], "date outside 1800")
  expect_match(out$read_issue[2], "date outside 1800")
  expect_true(is.na(out$read_issue[3]))
})

test_that("15 extra columns carry through, and a repeated header is kept distinct", {
  out <- rd("15_extra_columns_and_repeated_header.csv")
  expect_true(all(c("Flag", "Flag.1", "Remark") %in% names(out)))
  expect_equal(out$Flag, c("A", ""))
  expect_equal(out$Flag.1, c("x", "y"))
  expect_equal(out$Remark, c("FALLING", ""))
})

test_that("16 any headers can be mapped, and a wrong one lists the columns", {
  out <- rd("16_custom_headers.csv", station_id = "Site", date = "When", time = "Clock",
            stage = "Level (m)", discharge = "Q (m3/s)")
  expect_equal(out$stage_m, c(1.6, 0.85))
  expect_equal(out$station_id, c("10250", "10250"))
  expect_error(rd("16_custom_headers.csv"), "not found.*Station number.*The columns are")
})

test_that("17 a spreadsheet reads, with Excel dates recognised and the sheet chosen", {
  skip_if_not_installed("readxl")
  out <- rd("17_spreadsheet.xlsx", sheet = "Gaugings")
  expect_equal(nrow(out), 3L)
  expect_equal(out$stage_m, c(1.6, 0.85, 1.885))
  expect_equal(out$observation_time[1], at_utc("1970-02-13 12:47:00"))
  expect_equal(attr(read_summary(out), "date_format"), "Excel serial")
  expect_equal(out$read_issue[2], "discharge missing")  # "---" is a placeholder
  # The first sheet is not the data, so the default fails clearly.
  expect_error(rd("17_spreadsheet.xlsx"), "not found")
})

test_that("17 a spreadsheet without readxl stops with an instruction, not a crash", {
  testthat::local_mocked_bindings(.has_readxl = function() FALSE)
  expect_error(.read_text_table(fx("17_spreadsheet.xlsx"), "read_gaugings()"), "install.packages")
})

test_that("18 a byte-order mark, CRLF endings, blank lines and a quoted comma read cleanly", {
  out <- rd("18_bom_quotes_blank_lines_crlf.csv")
  expect_equal(nrow(out), 2L)
  expect_equal(out$station_id, c("10250", "10,250"))
  expect_equal(out$source_row, 1:2)
  expect_equal(names(out)[2], "station_id")
})

test_that("a file with only a header returns an empty table without error", {
  out <- rd("19_header_only.csv")
  expect_equal(nrow(out), 0L)
  expect_true(all(c("stage_m", "read_issue") %in% names(out)))
  expect_equal(nrow(read_summary(out)), 0L)
})

test_that("a Latin-1 file reads when its encoding is given", {
  out <- rd("20_latin1_station_name.csv", encoding = "Latin-1")
  expect_equal(out$station_name, "Café Bridge")
})

# ---- the summary, time zones and the evidence hand-off ---------------------

test_that("read_summary counts rows per issue, most common first, and survives only an untouched table", {
  out <- rd("05_placeholders.csv")
  s <- read_summary(out)
  expect_false(is.unsorted(rev(s$n_rows)))
  expect_equal(s$n_rows[s$issue == "stage missing"], 2L)
  expect_equal(s$n_rows[s$issue == "discharge missing"], 2L)
  expect_equal(s$share_of_rows[s$issue == "stage missing"], 0.5)
  expect_equal(attr(s, "rows"), 4L)
  expect_equal(attr(s, "rows_with_note"), 3L)
  expect_equal(attr(s, "source"), "05_placeholders.csv")
  expect_error(read_summary(out[1:2]), "no longer matches")
  expect_error(read_summary(data.table::data.table(x = 1)), "no read summary")
})

test_that("the printed message and the summary table agree", {
  expect_message(read_gaugings(fx("05_placeholders.csv")), "4 rows, 1 stations")
  expect_message(read_gaugings(fx("05_placeholders.csv")), "stage missing \\(2\\)")
})

test_that("a clock time is kept as written in any time zone", {
  utc <- rd("01_clean_wiski.csv")
  london <- rd("01_clean_wiski.csv", tz = "Europe/London")
  # 13/02/1970 is winter; 05/05/1970 is in British Summer Time. The wall
  # clock must read 13:02 either way, not be shifted by the offset.
  expect_equal(format(london$observation_time[2], "%H:%M"), "13:02")
  expect_equal(format(london$observation_time[1], "%H:%M"), "12:47")
  expect_equal(attr(london$observation_time, "tzone"), "Europe/London")
  expect_equal(format(utc$observation_time[2], "%H:%M"), "13:02")
})

test_that("a clock time that does not exist in the zone is NA, not shifted", {
  raw <- data.frame(`Station number` = "1", Date = "28/03/2021", Time = "01:30:00",
                    Stage = "1", Flow = "2", check.names = FALSE)
  out <- read_gaugings(raw, tz = "Europe/London", quiet = TRUE)
  expect_true(is.na(out$observation_time))
})

test_that("read_gaugings output converts to evidence with ids, sites, source and exclusions", {
  out <- rd("05_placeholders.csv")
  ev <- as_flode_evidence(out)
  expect_true(S7::S7_inherits(ev, FlodeEvidence))
  expect_equal(nrow(ev), 4L)
  expect_equal(ev$site_id, rep("10250", 4))
  expect_equal(ev$source_name, rep("05_placeholders.csv", 4))
  expect_equal(ev$included, c(FALSE, FALSE, FALSE, TRUE))
  expect_equal(ev$exclusion_reason[1], "stage missing")
  expect_true(is.na(ev$exclusion_reason[4]))
  expect_equal(ev$source_row, 1:4)
  expect_equal(ev$observation_time, out$observation_time)
  expect_silent(S7::validate(ev))
})

test_that("a data.frame input reads as before and is labelled as such", {
  raw <- data.frame(`Station number` = "1", Date = "13/02/1970", Time = "12:00:00",
                    Stage = "1", Flow = "2", check.names = FALSE)
  out <- read_gaugings(raw, quiet = TRUE)
  expect_equal(attr(read_summary(out), "source"), "data.frame")
  expect_equal(out$stage_original, "1")
})

test_that("keep_original = FALSE drops the original-text columns", {
  out <- rd("01_clean_wiski.csv", keep_original = FALSE)
  expect_false(any(grepl("_original$", names(out))))
})

test_that("dec must be a point or a comma", {
  expect_error(rd("01_clean_wiski.csv", dec = ";"), "dec must be")
})
